-- Imports external numeric monster HP/MP and combat attribute evidence from the 17173 evidence pack.
-- Game function: monster MP/HP and combat attribute black-box calibration evidence.
-- Source Chinese names/maps are intentionally not stored because the source text is Simplified Chinese.
CREATE TABLE IF NOT EXISTS `god2_game_meta`.`monster_attribute_external_numeric_evidence` (
  `evidence_id` bigint NOT NULL AUTO_INCREMENT,
  `source_row_number` int NOT NULL,
  `source_page` int NULL,
  `source_level` int NULL,
  `reference_hp` int NULL,
  `reference_mp` int NULL,
  `physical_attack` int NULL,
  `magic_attack` int NULL,
  `physical_defense` int NULL,
  `magic_defense` int NULL,
  `base_exp` int NULL,
  `strength` int NULL,
  `constitution` int NULL,
  `intelligence` int NULL,
  `speed` int NULL,
  `metal` int NULL,
  `wood` int NULL,
  `water` int NULL,
  `fire` int NULL,
  `earth` int NULL,
  `source_url` varchar(500) NOT NULL,
  `source_sha256` char(64) NOT NULL,
  `client_name_big5_hex` varchar(64) NULL,
  `candidate_enyname_keys` varchar(500) NULL,
  `identity_join_basis` varchar(128) NULL,
  `comparison_status` varchar(128) NOT NULL,
  `authority_note` varchar(300) NOT NULL,
  `imported_at_utc` datetime(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),
  PRIMARY KEY (`evidence_id`),
  KEY `ix_monster_attribute_external_numeric_evidence_level` (`source_level`),
  KEY `ix_monster_attribute_external_numeric_evidence_candidate` (`candidate_enyname_keys`(120))
) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
TRUNCATE TABLE `god2_game_meta`.`monster_attribute_external_numeric_evidence`;
CREATE OR REPLACE VIEW `god2_game_meta`.`vw_monster_attribute_external_numeric_evidence_readable` AS
SELECT `source_row_number` AS `source_row_number`, `source_page` AS `source_page`, `source_level` AS `level`, `reference_hp` AS `external_hp`, `reference_mp` AS `external_mp`, `physical_attack` AS `external_physical_attack`, `magic_attack` AS `external_magic_attack`, `physical_defense` AS `external_physical_defense`, `magic_defense` AS `external_magic_defense`, `base_exp` AS `external_exp`, `strength` AS `strength`, `constitution` AS `constitution`, `intelligence` AS `intelligence`, `speed` AS `speed`, `metal` AS `metal`, `wood` AS `wood`, `water` AS `water`, `fire` AS `fire`, `earth` AS `earth`, `candidate_enyname_keys` AS `client_candidate_keys`, `identity_join_basis` AS `identity_join_basis`, `comparison_status` AS `verification_status`, `authority_note` AS `authority_boundary` FROM `god2_game_meta`.`monster_attribute_external_numeric_evidence`;
